        lines.push("");
    }
    if (data.cookies.analytics) {
        lines.push("分析 Cookie");
        lines.push("这些 Cookie 帮助我们了解访问者如何与网站互动，通过收集和报告匿名信息。这些数据帮助我们改进网站性能和用户体验。");
