    if (data.cookies.social) {
        lines.push("社交媒体 Cookie");
        lines.push("这些 Cookie 由社交媒体服务（如 Facebook、Twitter、LinkedIn）设置，允许您与朋友和网络分享我们的内容。它们能够跟踪您在其他网站上的浏览行为，并建立您的兴趣档案。");
        lines.push("");
