        lines.push("");
    }
    lines.push(sectionNum++ + ". 政策更新");
    lines.push("");
    lines.push("我们可能会不时更新本 Cookie 政策以反映我们实践的变化或其他运营、法律或监管原因。请定期查看本页面以获取最新信息。");
