        lines.push("邮箱：" + data.contactEmail);
        lines.push("网站：" + data.websiteUrl);
        lines.push("");
    }
    lines.push("---");
    lines.push(data.companyName);
    lines.push("最后更新：" + lastUpdated);
    return lines.join("\n");
}
